    questions: [
      { question: { en: "Which part of a knife is commonly used to remove fish scales, rather than the sharp cutting edge?" }, answers: ["The tip of the blade", "The spine, or dull back edge, of the knife", "The handle", "The bolster only"], correctIndex: 1, explanation: { en: "Scales are commonly removed using the spine (dull back edge) of a knife, a dedicated scaling tool, or a blade held at a shallow angle." } },
      { question: { en: "In which direction should a chef scrape to remove scales effectively?" }, answers: ["From head toward tail, following the natural lay of the scales", "From tail toward head, against the natural lay of the scales", "In small circular motions regardless of direction", "It does not matter as long as pressure is firm"], correctIndex: 1, explanation: { en: "Scales lie from head to tail like overlapping tiles, so scraping from tail toward head catches each scale's edge and lifts it away." } },
      { question: { en: "What is the risk of applying too much pressure while scaling?" }, answers: ["The scales will not come off at all", "The flesh beneath the skin can become bruised", "The knife blade will become permanently blunt", "It will cause the fish to spoil faster"], correctIndex: 1, explanation: { en: "Excessive pressure can push through the thin skin and bruise the delicate flesh directly beneath it." } },
      { question: { en: "Besides cleanliness, why is scaling under running water considered good practice?" }, answers: ["It makes the scales grow back faster", "It rinses loosened scales away and gives a clearer view of remaining progress", "It is required by law in all professional kitchens", "It has no functional benefit beyond tradition"], correctIndex: 1, explanation: { en: "Running water clears loosened scales as they come free, giving the chef an unobstructed view of how much surface remains to be scaled." } },
    ],
