    questions: [
      { question: { en: "What does the name \"yanagiba\" refer to?" }, answers: ["The blacksmith who invented it", "The shape of a willow leaf", "A river in Japan", "The type of fish it was first used on"], correctIndex: 1, explanation: { en: "Yanagiba means \"willow blade,\" referring to the knife's long, narrow, gently tapered shape resembling a willow leaf." } },
      { question: { en: "Why is a yanagiba typically much longer than a Western chef's knife?" }, answers: ["Longer blades are simply a fashion trend", "It needs enough length to complete a wide cut of fish in a single uninterrupted pull", "Length has no functional purpose", "It makes the knife easier to store"], correctIndex: 1, explanation: { en: "The extra length allows the blade to travel across the entire width of a piece of fish in one continuous pull, avoiding a visible seam from multiple strokes." } },
      { question: { en: "What happens if a blade is too short to finish a wide slice in one pull?" }, answers: ["Nothing, the cut looks identical either way", "The chef must stop and add a second stroke, leaving a visible seam on the cut surface", "The fish becomes unsafe to eat", "The knife will break"], correctIndex: 1, explanation: { en: "A shorter blade running out of length partway through a cut forces a second stroke, which leaves a visible seam or ridge on the finished surface." } },
      { question: { en: "Which part of the yanagiba is used for delicate, precise work?" }, answers: ["The handle", "The wider base near the handle", "The pointed tip", "The spine of the blade"], correctIndex: 2, explanation: { en: "The pointed tip is reserved for delicate, precise work, while the wider base near the handle carries more cutting power for thicker sections." } },
    ],
